<template><div v-loading="loading"><div class="welcome-banner"><div><span class="banner-kicker">YOUR DAILY WORKSPACE</span><h2>{{greeting}}，{{user.display_name}}</h2><p>今天的诊疗工作，从清晰的信息开始。</p><el-button class="banner-button" @click="$emit('navigate',destination)">进入{{label(user.role_code==='ADMIN'?'CASHIER':user.role_code)}}工作台 <i class="el-icon-right"/></el-button></div><div class="banner-art"><div class="art-circle"/><div class="art-cross">✚</div><span class="art-label">CARE · CONNECTED</span></div></div><div class="metric-grid"><div class="metric" v-for="m in metrics" :key="m.name"><span>{{m.name}}</span><strong>{{m.value}}</strong><small>{{m.caption}}</small></div></div><section class="card"><div class="card-heading"><div><h2>最近业务记录</h2><p>根据当前岗位显示已授权的数据</p></div><el-button icon="el-icon-refresh" @click="load">刷新</el-button></div><el-table :data="recent" empty-text="暂无业务记录，可以从工作台开始"><el-table-column prop="patient_name" label="患者" min-width="100"/><el-table-column prop="case_no" label="病历号" min-width="190"/><el-table-column v-if="isClinical" prop="department_name" label="科室"/><el-table-column v-else prop="item_name" label="项目"/><el-table-column label="状态" width="120"><template slot-scope="s"><Status :value="s.row.status||s.row.execution_status" :execution="!isClinical"/></template></el-table-column><el-table-column label="时间" min-width="165"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column></el-table></section><div class="workflow-strip"><div><b>01</b><span>窗口挂号<small>核对信息并完成缴费</small></span></div><i class="el-icon-arrow-right"/><div><b>02</b><span>门诊诊疗<small>病历、初诊与医嘱</small></span></div><i class="el-icon-arrow-right"/><div><b>03</b><span>医技执行<small>登记、执行与结果回传</small></span></div><i class="el-icon-arrow-right"/><div><b>04</b><span>药房发药<small>按处方核对并发放</small></span></div></div></div></template>
<script>import{api,label,date}from'../api';import Status from'../components/Status.vue';export default{components:{Status},props:['user'],data:()=>({loading:false,stats:[],recent:[]}),computed:{isClinical(){return['ADMIN','DOCTOR','CASHIER'].includes(this.user.role_code);},greeting(){return new Date().getHours()<12?'上午好':new Date().getHours()<18?'下午好':'晚上好';},destination(){return{ADMIN:'registration',CASHIER:'registration',DOCTOR:'clinic',CHECK:'execution',LAB:'execution',TREAT:'execution',PHARMACY:'pharmacy'}[this.user.role_code];},metrics(){const count=status=>Number(this.stats.find(x=>x.status===status)?.total||0);const total=this.stats.reduce((s,x)=>s+Number(x.total),0);return this.isClinical?[{name:'就诊记录',value:total,caption:'当前岗位可见的累计记录'},{name:'等待接诊',value:count('REGISTERED'),caption:'已挂号缴费 · 尚未看诊'},{name:'正在诊疗',value:count('IN_PROGRESS')+count('DIAGNOSED'),caption:'持续关注患者诊疗进展'},{name:'完成就诊',value:count('COMPLETED'),caption:'所有业务已处理'}]:[{name:'项目总数',value:total,caption:'当前岗位可见项目'},{name:'待处理',value:count('PENDING'),caption:'核实收费后执行'},{name:'正在执行',value:count('REGISTERED'),caption:'已完成登记'},{name:'已完成',value:count('COMPLETED')+count('DISPENSED'),caption:'结果或发药已完成'}];}},created(){this.load();},methods:{label,date,async load(){this.loading=true;try{const d=await api.get('/dashboard');this.stats=d.stats;this.recent=d.recent;}catch{}finally{this.loading=false;}}}};</script>
